const items = $input.all();

const lists = items
  .map(i => i.json)
  .filter(item =>
    item !== null &&
    typeof item === 'object' &&
    !Array.isArray(item) &&
    item.id !== undefined
  );

return lists.map(list => ({
  json: {
    list_id: String(list.id),
    list_name: list.name ?? ''
  }
}));

const CLIENT_ID = 'manami';
const INGESTED_AT = new Date().toISOString();
const SNAPSHOT_DATE = INGESTED_AT.slice(0, 10);
const num = v => (v === null || v === undefined || v === '' ? 0 : Number(v));

function parseCzDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  // ISO already? (e.g. "2025-06-15T..." or "2025-06-15")
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s;
  // Czech format "D.M.YYYY" or "D. M. YYYY"
  const m = s.match(/^(\d{1,2})\.\s*(\d{1,2})\.\s*(\d{4})$/);
  if (m) {
    const [, d, mo, y] = m;
    return `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}T00:00:00Z`;
  }
  return null; // unparseable → null, don't crash BQ
}

return $input.all().map(item => {
  const d    = item.json.list ?? {};
  const subs = item.json.subscribers ?? {};

  const row = {
    list_id:            String(d.id ?? ''),
    list_name:          d.name ?? '',
    active_subscribers: num(d.active_subscribers),
    subscribed:         num(subs.subscribed),
    unsubscribed:       num(subs.unsubscribed),
    hard_bounced:       num(subs.hard_bounced),
    soft_bounced:       num(subs.soft_bounced),
    complained:         num(subs.complained),
    unconfirmed:        num(subs.unconfirmed),
    unknown:            num(subs.unknown),
    currency:           d.settings?.currency ?? '',
    locale:             d.settings?.locale ?? '',
    created:            parseCzDate(d.created)
  };

  return {
    json: {
      client_id:     CLIENT_ID,
      ingested_at:   INGESTED_AT,
      snapshot_date: SNAPSHOT_DATE,
      ...row,
      payload_json:  JSON.stringify(item.json)
    }
  };
});

const stats = $input.first().json.stats;
const CLIENT_ID = 'manami';
const INGESTED_AT = new Date().toISOString();

function parseEcomailDate(raw) {
  if (!raw) return null;
  const s = String(raw);
  if (s.length === 14) {
    return `${s.slice(0,4)}-${s.slice(4,6)}-${s.slice(6,8)}T${s.slice(8,10)}:${s.slice(10,12)}:${s.slice(12,14)}Z`;
  }
  return s;
}

const num = v => (v === null || v === undefined || v === '' ? 0 : Number(v));
const rnd = (v, d) => { const n = Number(v); const f = Math.pow(10, d); return Math.round((n + Number.EPSILON) * f) / f; };  // BQ NUMERIC guard: no float noise

return Object.entries(stats || {}).map(([campaignId, data]) => {
  const row = {
    campaign_id:       String(campaignId),
    title:             data.title ?? '',
    sent_at:           parseEcomailDate(data.sent_at),
    inject:            num(data.inject),
    delivery:          num(data.delivery),
    delivery_rate:     rnd(data.delivery_rate, 4),
    open:              num(data.open),
    total_open:        num(data.total_open),
    open_rate:         rnd(data.open_rate, 4),
    click:             num(data.click),
    total_click:       num(data.total_click),
    click_rate:        rnd(data.click_rate, 4),
    bounce:            num(data.bounce),
    bounce_rate:       rnd(data.bounce_rate, 4),
    spam:              num(data.spam),
    spam_rate:         rnd(data.spam_rate, 4),
    unsub:             num(data.unsub),
    unsub_rate:        rnd(data.unsub_rate, 4),
    conversions:       num(data.conversions),
    conversions_value: rnd(data.conversions_value, 2),
    currency:          'CZK'
  };
  return {
    json: {
      client_id:    CLIENT_ID,
      ingested_at:  INGESTED_AT,
      payload_json: JSON.stringify(data),
      ...row
    }
  };
});

const items = $input.all();

return items
  .map(i => i.json)
  .filter(p => p !== null && typeof p === 'object' && p.id !== undefined)
  .map(p => ({
    json: {
      pipeline_id: String(p.id),
      list_id: String(p.list_id ?? ''),
      name: p.name ?? '',
      created_at: p.created_at ?? '',
      updated_at: p.updated_at ?? ''
    }
  }));

const items = $input.all();
const num = v => (v === null || v === undefined || v === '' ? 0 : Number(v));
const rnd = (v, d) => { const n = Number(v); const f = Math.pow(10, d); return Math.round((n + Number.EPSILON) * f) / f; };  // BQ NUMERIC guard: no float noise

return items.map(item => {
  const s = item.json.stats ?? item.json;
  return {
    json: {
      pipeline_id:         String(s.pipeline_id ?? ''),
      triggered:           num(s.triggered),
      active:              num(s.active),
      ended:               num(s.ended),
      send:                num(s.send),
      inject:              num(s.inject),
      open:                num(s.open),
      total_open:          num(s.total_open),
      open_rate:           rnd(s.open_rate, 4),
      click:               num(s.click),
      total_click:         num(s.total_click),
      click_rate:          rnd(s.click_rate, 4),
      ctr:                 rnd(s.ctr, 4),
      bounce:              num(s.bounce),
      bounce_rate:         rnd(s.bounce_rate, 4),
      soft_bounce:         num(s.soft_bounce),
      hard_bounce:         num(s.hard_bounce),
      spam:                num(s.spam),
      unsub:               num(s.unsub),
      delivery_rate:       rnd(s.delivery_rate, 4),
      conversions:         num(s.conversions),
      conversions_value:   rnd(s.conversions_value, 2),
      conversions_average: rnd(s.conversions_average, 2),
      conversionrate:      rnd(s.conversionrate, 4)
    }
  };
});

const CLIENT_ID = 'manami';
const INGESTED_AT = new Date().toISOString();
const SNAPSHOT_DATE = INGESTED_AT.slice(0, 10);

const statsItem = $input.item.json;
const pipelineId = String(statsItem.pipeline_id ?? '');

const allPipelineItems = $('Extract pipeline IDs1').all();
const pipelineInfo = allPipelineItems.find(
  i => String(i.json.pipeline_id) === pipelineId
)?.json ?? {};

const merged = {
  pipeline_id:         pipelineId,
  list_id:             pipelineInfo.list_id ?? '',
  name:                pipelineInfo.name ?? '',
  created_at:          pipelineInfo.created_at || null,
  updated_at:          pipelineInfo.updated_at || null,
  metric_type:         'cumulative',
  triggered:           statsItem.triggered ?? 0,
  active:              statsItem.active ?? 0,
  ended:               statsItem.ended ?? 0,
  send:                statsItem.send ?? 0,
  inject:              statsItem.inject ?? 0,
  open:                statsItem.open ?? 0,
  total_open:          statsItem.total_open ?? 0,
  open_rate:           statsItem.open_rate ?? 0,
  click:               statsItem.click ?? 0,
  total_click:         statsItem.total_click ?? 0,
  click_rate:          statsItem.click_rate ?? 0,
  ctr:                 statsItem.ctr ?? 0,
  bounce:              statsItem.bounce ?? 0,
  bounce_rate:         statsItem.bounce_rate ?? 0,
  soft_bounce:         statsItem.soft_bounce ?? 0,
  hard_bounce:         statsItem.hard_bounce ?? 0,
  spam:                statsItem.spam ?? 0,
  unsub:               statsItem.unsub ?? 0,
  delivery_rate:       statsItem.delivery_rate ?? 0,
  conversions:         statsItem.conversions ?? 0,
  conversions_value:   statsItem.conversions_value ?? 0,
  conversions_average: statsItem.conversions_average ?? 0,
  conversionrate:      statsItem.conversionrate ?? 0
};

return {
  client_id:     CLIENT_ID,
  ingested_at:   INGESTED_AT,
  snapshot_date: SNAPSHOT_DATE,
  ...merged,
  payload_json:  JSON.stringify({ pipeline: pipelineInfo, stats: statsItem })
};
